using CADability.Attribute;
using CADability.Curve2D;
using CADability.UserInterface;
using System;
using System.Collections.Generic;
using System.Runtime.Serialization;

namespace CADability.GeoObject
{

    public class SurfaceOfRevolutionException : ApplicationException
    {
        public SurfaceOfRevolutionException(string msg) : base(msg) { }
    }
    /// <summary>
    /// A surface generated by rotating a curve about an axis. The curve may be any curve, it need not lie in a plane
    /// with the axis, nor in a plane at all. u is the angle of rotation about the axis (right handed with respect to
    /// <see cref="Axis"/>), v is the natural parameter of the curve: the parameter which
    /// <see cref="ICurve.PositionToParameter"/> assigns to a position on the curve, running linearly from the
    /// parameter of position 0 to the parameter of position 1.
    /// <para>
    /// Formerly the curve was a 2d curve in the xy plane, rotated about the y axis and placed by a ModOp, with v
    /// running from a start to an end parameter. That implementation is gone; files only contain the curve and the
    /// axis.
    /// </para>
    /// </summary>
    [Serializable()]
    public class SurfaceOfRevolution : ISurfaceImpl, ISurfaceOfRevolution, ISerializable, IExportStep, IJsonSerialize, IJsonSerializeDone
    {
        private ICurve curveToRotate; // not necessarily in a plane with the axis, but often is
        private GeoPoint axisLocation;
        private GeoVector axisDirection;
        // The parameters of position 0 and position 1 of curveToRotate. v is mapped linearly to the position of the
        // curve with these values (see ToPosition). Not every curve does that in ParameterToPosition: a Path maps
        // by the length along the path, which is not the inverse of its PositionToParameter, and an Ellipse wraps
        // a parameter outside of its range by 2*pi.
        private double vStart, vEnd;
        private bool rangeKnown; // vStart and vEnd are calculated on demand: while reading a file the curve may not be complete
        // whether curveToRotate lies in a plane with the axis, null when not yet determined
        private bool? inPlaneWithAxis;

        public SurfaceOfRevolution(ICurve basisCurve, GeoPoint axisLocation, GeoVector axisDirection) : base()
        {
            this.axisLocation = axisLocation;
            this.axisDirection = axisDirection;
            SetCurve(basisCurve);
            domain = BoundingRect.EmptyBoundingRect;
        }
        private void SetCurve(ICurve curve)
        {
            curveToRotate = curve;
            rangeKnown = false;
            inPlaneWithAxis = null;
        }
        private double VStart
        {
            get
            {
                if (!rangeKnown) CalculateRange();
                return vStart;
            }
        }
        private double VEnd
        {
            get
            {
                if (!rangeKnown) CalculateRange();
                return vEnd;
            }
        }
        private void CalculateRange()
        {
            vStart = curveToRotate.PositionToParameter(0.0);
            vEnd = curveToRotate.PositionToParameter(1.0);
            rangeKnown = true;
        }
        /// <summary>
        /// Returns the location of the axis of revolution
        /// </summary>
        public GeoPoint Location
        {
            get
            {
                return axisLocation;
            }
        }
        /// <summary>
        /// Returns the direction of the axis of revolution
        /// </summary>
        public GeoVector Axis
        {
            get
            {
                return axisDirection;
            }
        }
        /// <summary>
        /// Returns the curve that is rotated to form this surface
        /// </summary>
        public ICurve BasisCurve
        {
            get
            {
                return curveToRotate;
            }
        }
        /// <summary>
        /// The position on <see cref="curveToRotate"/> of the parameter <paramref name="v"/>.
        /// </summary>
        private double ToPosition(double v)
        {
            return (v - VStart) / (VEnd - VStart);
        }
        /// <summary>
        /// The parameter v of the <paramref name="position"/> on <see cref="curveToRotate"/>.
        /// </summary>
        private double ToParameter(double position)
        {
            return VStart + position * (VEnd - VStart);
        }
        /// <summary>
        /// d(position)/d(v), the factor by which derivatives with respect to the position of the curve become
        /// derivatives with respect to v.
        /// </summary>
        private double PositionPerParameter
        {
            get
            {
                return 1.0 / (VEnd - VStart);
            }
        }
        private ModOp Rotation(double u)
        {
            return ModOp.Rotate(axisLocation, axisDirection, (SweepAngle)u);
        }
        /// <summary>
        /// The point of the curve at the parameter <paramref name="v"/> and its first and second derivative with respect
        /// to v. <see cref="ICurve.TryPointDeriv2At"/> differentiates by the position; curves which don't implement it
        /// (e.g. Polyline) are differenced numerically. <see cref="ICurve.DirectionAt"/> is not used: it is only
        /// required to give the direction, and Path, for instance, gives the derivative of its segment, not of itself.
        /// The point is always taken from <see cref="ICurve.PointAt"/>: the numerical TryPointDeriv2At of GeneralCurve
        /// moves positions at the very ends of the curve slightly inwards, and the point of the derivatives must be the
        /// point of <see cref="PointAt"/>.
        /// </summary>
        private void CurveDerivatives(double v, out GeoPoint point, out GeoVector deriv1, out GeoVector deriv2)
        {
            double pos = ToPosition(v);
            point = curveToRotate.PointAt(pos);
            if (curveToRotate.TryPointDeriv2At(pos, out GeoPoint _, out GeoVector d1, out GeoVector d2))
            {
                double f = PositionPerParameter;
                deriv1 = f * d1;
                deriv2 = (f * f) * d2;
                return;
            }
            // central differences; the second derivative with a larger step, its rounding error grows with 1/h^2
            double h = 1e-5 * (VEnd - VStart);
            deriv1 = (1.0 / (2.0 * h)) * (curveToRotate.PointAt(ToPosition(v + h)) - curveToRotate.PointAt(ToPosition(v - h)));
            double h2 = 1e-3 * (VEnd - VStart);
            GeoPoint pp = curveToRotate.PointAt(ToPosition(v + h2));
            GeoPoint pm = curveToRotate.PointAt(ToPosition(v - h2));
            deriv2 = (1.0 / (h2 * h2)) * ((pp - point) + (pm - point));
        }
        #region ISurfaceImpl overrides
